import unittest
from math_ops import multiply

class TestMath(unittest.TestCase):
    def test_two(self):
        self.assertEqual(multiply(2, 3), 6)
    def test_three(self):
        self.assertEqual(multiply(3, 4), 12)
    def test_four(self):
        self.assertEqual(multiply(5, 5), 25)
